    'proposals_outbox_au',
  );
  final i1.Trigger proposalsNoDelete = i1.Trigger(
    'CREATE TRIGGER proposals_no_delete BEFORE DELETE ON proposals BEGIN SELECT RAISE (ABORT, \'tombstone, never delete\');END',
